import random


def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    me = [h[0] for h in history]
    op = [h[1] for h in history]

    # Counts
    my_c = my_d = 0
    for a in me:
        if a == 'C':
            my_c += 1
        else:
            my_d += 1
    op_c = 0
    for a in op:
        if a == 'C':
            op_c += 1
    op_d = n - op_c

    # Recent window statistics
    w = 8 if n >= 8 else n
    rec_op_c = 0
    rec_op_d = 0
    rec_my_c = 0
    rec_my_d = 0
    rec_cd = 0  # we C, opp D
    rec_dc = 0  # we D, opp C
    rec_cc = 0
    rec_dd = 0
    for i in range(n - w, n):
        a, b = history[i]
        if a == 'C':
            rec_my_c += 1
            if b == 'C':
                rec_cc += 1
                rec_op_c += 1
            else:
                rec_cd += 1
                rec_op_d += 1
        else:
            rec_my_d += 1
            if b == 'C':
                rec_dc += 1
                rec_op_c += 1
            else:
                rec_dd += 1
                rec_op_d += 1

    last_me = me[-1]
    last_op = op[-1]

    # Endgame: against a reliably cooperative opponent, cash in.
    if n >= 90:
        if op_c >= n - 2 or (n - op_c) <= n // 12:
            return 'D'
        if op_d == 0:
            return 'D'

    # Persistent defector detection: if opponent rarely cooperates, defect hard.
    if n >= 6 and op_c * 4 <= n:
        # Probe rarely to see if they've changed
        if last_op == 'C' and rec_dc >= 1:
            return 'C'
        if rng.random() < 0.06:
            return 'C'
        return 'D'

    # If last was mutual defection, break the spiral with some probability.
    if last_me == 'D' and last_op == 'D':
        if rec_dd >= 3 and rec_cc == 0:
            if rng.random() < 0.7:
                return 'C'
        if rng.random() < 0.25:
            return 'C'
        return 'D'

    # Opponent just defected. Retaliate, but forgive if history is good.
    if last_op == 'D':
        # If opponent has been very cooperative overall, be forgiving.
        if op_d <= 2 and n >= 4:
            # Single (or rare) defection: forgive often to keep CC.
            if rng.random() < 0.75:
                return 'C'
            return 'D'
        if op_d <= n // 6:
            if rng.random() < 0.5:
                return 'C'
            return 'D'
        # Not so cooperative: retaliate
        return 'D'

    # Opponent cooperated last. Mostly cooperate.
    # Occasional probe against very cooperative opponents to gain DC.
    if op_d == 0 and n >= 5:
        # Punish-free exploitation window: defect now and then.
        if n >= 85:
            return 'D' if rng.random() < 0.5 else 'C'
        if rng.random() < 0.05:
            return 'D'
        return 'C'

    # If we've been exploiting and opponent still cooperates a lot, continue lightly.
    if last_me == 'D' and last_op == 'C':
        if rec_dc >= 2 and op_c >= n - op_d and op_d <= n // 5:
            if rng.random() < 0.35:
                return 'D'
        return 'C'

    # If we defected last round against their cooperation, repair.
    if rec_dc > rec_cd + 2:
        return 'C'

    # Nearly all-cooperator opponent: exploit a bit but keep them happy.
    if op_d <= 1 and n >= 6:
        if n >= 80:
            return 'D' if rng.random() < 0.6 else 'C'
        if rng.random() < 0.06:
            return 'D'
        return 'C'

    # Default: cooperate (tit-for-tat-ish, already handled last-op-D).
    return 'C'
